/**
 * voice-reader.js — the "Pakinggan" player.
 *
 * Plays a post aloud in English, Filipino or Manobo. Shared by the three
 * resident detail pages and by the staff preview in the admin forms.
 *
 * Two audio sources, in this order:
 *
 *   1. A cached MP3, generated by a real text-to-speech provider when staff
 *      published the post. Same voice on every phone, and nothing is
 *      synthesised while the resident waits.
 *   2. The device's own speech engine, for a language whose MP3 does not exist
 *      yet or has gone stale. This is what makes the feature survive a missing
 *      provider key, an expired free tier, or a post edited five minutes ago.
 *
 * Accessibility feature first, so the awkward parts of the browser APIs are
 * handled here rather than left to fail in front of an elderly resident:
 *
 *   - Chrome stops speaking after roughly fifteen seconds of one utterance.
 *     The script arrives pre-split into short sentences (SpokenText.php), each
 *     spoken as its own utterance, with a keep-alive resume() and a watchdog
 *     that restarts the queue if the engine goes quiet anyway.
 *   - iOS Safari only starts audio from inside the tap that asked for it, so
 *     play() reaches .play() / speechSynthesis.speak() with nothing awaited.
 *   - Android Chrome never resumes a paused utterance, so pause there stops
 *     and remembers the sentence, and resume speaks it again from its start.
 *   - getVoices() is asynchronous, and a device with no Filipino voice is told
 *     so plainly instead of reading Tagalog in an American accent.
 *
 * Sentence highlighting works for both sources. With speech it follows the
 * engine's own utterance boundaries; with an MP3 it follows playback time,
 * split across the sentences in proportion to their length — the MP3 was
 * generated from those same sentences at a constant rate, so it tracks well.
 */
(function () {
    'use strict';

    if (window.__voiceReaderRegistered) { return; }
    window.__voiceReaderRegistered = true;

    var SPEECH  = typeof window.speechSynthesis !== 'undefined' && !!window.SpeechSynthesisUtterance;
    var ANDROID = /Android/i.test(navigator.userAgent || '');
    var REDUCED = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /**
     * Carries "keep reading in this language" across the full-page reload
     * that switching the page language causes (see chooseLanguage()/
     * _goToLanguage() below). sessionStorage rather than a query string so it
     * survives exactly one navigation and leaves no trace in the URL.
     */
    var RESUME_KEY = 'bg_voice_resume';

    /**
     * Rough quality signal from a voice's own name — there is no standard API
     * for this. Edge exposes its neural voices as "Microsoft ... Online
     * (Natural)"; Chrome/Android sometimes label a better engine "Enhanced" or
     * "Premium". Ranked higher only among voices that already match the
     * language being asked for, never instead of a language match.
     */
    function voiceQuality(voice) {
        var name = (voice.name || '').toLowerCase();
        if (name.indexOf('online') !== -1 || name.indexOf('natural') !== -1) { return 3; }
        if (name.indexOf('enhanced') !== -1 || name.indexOf('premium') !== -1) { return 2; }
        if (voice.localService === false) { return 1; }   // network voices are usually better than the on-device default
        return 0;
    }

    /**
     * Best available device voice for a list of language tags, best first.
     * Returns null when the device has nothing for any of them.
     */
    function pickVoice(candidates) {
        if (!SPEECH || !candidates || !candidates.length) { return null; }

        var voices = window.speechSynthesis.getVoices() || [];
        if (!voices.length) { return null; }

        for (var i = 0; i < candidates.length; i++) {
            var want = candidates[i].toLowerCase();
            var base = want.split('-')[0];

            var exact = [];
            var byBase = [];
            for (var j = 0; j < voices.length; j++) {
                var lang = (voices[j].lang || '').toLowerCase().replace('_', '-');
                if (lang === want) { exact.push(voices[j]); }
                else if (lang === base || lang.indexOf(base + '-') === 0) { byBase.push(voices[j]); }
            }

            var pool = exact.length ? exact : byBase;
            if (!pool.length) { continue; }

            pool.sort(function (a, b) { return voiceQuality(b) - voiceQuality(a); });
            return pool[0];
        }
        return null;
    }

    /** Run cb once the voice list is populated — it arrives asynchronously. */
    function whenVoicesReady(cb) {
        if (!SPEECH) { return; }
        if ((window.speechSynthesis.getVoices() || []).length) { cb(); return; }

        var done  = false;
        var fire  = function () { if (!done) { done = true; cb(); } };
        var prior = window.speechSynthesis.onvoiceschanged;

        window.speechSynthesis.onvoiceschanged = function () {
            if (typeof prior === 'function') { try { prior(); } catch (e) {} }
            fire();
        };
        setTimeout(fire, 1200);      // some builds fill the list without firing
    }

    /** 0.1 s of silence — played inside the user's tap so iOS lets the clip element play later. */
    var SILENCE = 'data:audio/wav;base64,UklGRigAAABXQVZFZm10IBAAAAABAAEARKwAAIhYAQACABAAZGF0YQQAAAAAAA==';

    /**
     * Plays a voice-dataset segment plan: recorded clips of native speakers in
     * order, with the device voice reading the words nobody has recorded yet.
     *
     * One instance per player. The Resident Voice Reader and the admin
     * Interactive Voice Tester both use this, on plans from the same server
     * resolver, so the admin preview is exactly what residents hear.
     *
     * Only one segment ever sounds at a time: every play() or stop() bumps a
     * token, and callbacks from an older run see the stale token and do nothing.
     */
    function VoiceSegmentPlayer() {
        this.clip     = null;
        this.token    = 0;
        this.active   = false;
        this.paused   = false;
        this._preload = null;
    }

    VoiceSegmentPlayer.prototype = {
        /** Call from inside the click handler that starts playback (iOS). */
        unlock: function () {
            if (!this.clip) { this.clip = new Audio(); this.clip.preload = 'auto'; }
            if (!this.clip.src) {
                try { this.clip.src = SILENCE; var p = this.clip.play(); if (p && p.catch) { p.catch(function () {}); } } catch (e) {}
            }
        },

        /**
         * @param {Array}  segments  [{type:'recorded', text, audio_url} | {type:'missing', text}]
         * @param {Object} opts      lang, voice, rate, onSegment(i, seg), onDone(), onSpeechError(event)
         */
        play: function (segments, opts) {
            this.stop();
            this.unlock();
            this.active = true;
            this.paused = false;
            this._run(segments || [], opts || {}, 0, ++this.token);
        },

        _run: function (segments, opts, i, token) {
            var self = this;
            if (token !== this.token) { return; }
            if (this.paused) {   // paused between two segments: hold the place until resume()
                this._pendingRun = function () { self._run(segments, opts, i, token); };
                return;
            }
            if (i >= segments.length) {
                this.active = false;
                if (opts.onDone) { opts.onDone(); }
                return;
            }

            var seg  = segments[i];
            var next = function () { self._run(segments, opts, i + 1, token); };
            if (opts.onSegment) { opts.onSegment(i, seg); }

            // Warm the cache for the next clip so recorded words follow each other without a gap.
            for (var k = i + 1; k < segments.length; k++) {
                if (segments[k].type === 'recorded' && segments[k].audio_url) {
                    this._preload = new Audio();
                    this._preload.preload = 'auto';
                    this._preload.src = segments[k].audio_url;
                    break;
                }
            }

            if (seg.type === 'recorded' && seg.audio_url) {
                var clip = this.clip;
                var fallback = function () {
                    if (token !== self.token) { return; }
                    clip.onended = clip.onerror = null;
                    if (opts.fallback === 'recorded_only') { next(); return; }   // never substitute a machine voice
                    self._say(seg.text, opts, next, token);   // the clip failed — read the words instead of skipping them
                };
                clip.onended = function () { if (token === self.token) { clip.onended = clip.onerror = null; next(); } };
                clip.onerror = fallback;
                clip.src = seg.audio_url;
                clip.playbackRate = opts.rate || 1;
                var p = clip.play();
                if (p && p.catch) { p.catch(fallback); }
                return;
            }

            // No recording for these words. Recorded-only mode skips them (they
            // are already counted for the admin's missing list); otherwise the
            // device voice reads them.
            if (opts.fallback === 'recorded_only') { setTimeout(next, 0); return; }
            this._say(seg.text, opts, next, token);
        },

        _say: function (text, opts, next, token) {
            var self = this;
            if (!SPEECH || !text) { next(); return; }

            var u = new SpeechSynthesisUtterance(text);
            u.lang   = opts.lang || 'fil-PH';
            u.rate   = opts.rate || 1;
            u.pitch  = 1;
            u.volume = 1;
            if (opts.voice) { u.voice = opts.voice; }
            u.onend   = function () { if (token === self.token) { next(); } };
            u.onerror = function (event) {
                if (token !== self.token || event.error === 'interrupted' || event.error === 'canceled') { return; }
                if (opts.onSpeechError) { opts.onSpeechError(event); } else { next(); }
            };
            window.speechSynthesis.speak(u);
        },

        /** True while a recorded clip (not the device voice) is sounding. */
        clipPlaying: function () {
            return !!(this.clip && !this.clip.paused && !this.clip.ended && this.clip.src !== SILENCE);
        },

        pause: function () {
            if (!this.active) { return; }
            this.paused = true;
            if (this.clip && !this.clip.paused) { this.clip.pause(); this._clipPaused = true; return; }
            this._clipPaused = false;
            if (SPEECH) { window.speechSynthesis.pause(); }
        },

        resume: function () {
            if (!this.active || !this.paused) { return; }
            this.paused = false;
            if (this._pendingRun) { var run = this._pendingRun; this._pendingRun = null; run(); return; }
            if (this._clipPaused && this.clip) { this.clip.play(); return; }
            if (SPEECH) { window.speechSynthesis.resume(); }
        },

        stop: function () {
            this.token++;
            this.active = false;
            this.paused = false;
            this._pendingRun = null;
            if (this.clip) {
                this.clip.onended = this.clip.onerror = null;
                try { this.clip.pause(); } catch (e) {}
            }
            if (SPEECH) { window.speechSynthesis.cancel(); }
        },
    };

    window.VoiceSegmentPlayer = VoiceSegmentPlayer;
    window.voicePickVoice     = pickVoice;
    window.voiceWhenReady     = whenVoicesReady;

    window.voiceReader = function () {
        return {
            /* ── State ───────────────────────────────────────────────────── */
            cfg:        null,
            available:  false,       // false hides the player entirely
            locale:     'fil',
            status:     'idle',      // 'idle' | 'playing' | 'paused'
            mode:       'speech',    // 'audio' | 'speech'
            rate:       1,
            progress:   0,
            current:    -1,
            chunks:     [],
            preferHuman: true,       // Manobo: recording over generated voice
            notice:     '',
            statusText: '',
            translating: null,       // locale code currently being translated on demand, or null

            _voice:     null,
            _total:     0,
            _before:    [],
            _audio:     null,
            _bodyHTML:  null,
            _cursor:    0,
            _spokenAt:  0,
            _keepAlive: null,
            _watchdog:  null,
            _stopping:  false,
            _lastMark:  -1,

            /* ── Setup ───────────────────────────────────────────────────── */

            init() {
                var raw = this.$el.querySelector('script[data-voice-config]');
                if (!raw) { return; }

                try {
                    this.cfg = JSON.parse(raw.textContent || '{}');
                } catch (e) {
                    return;                                   // malformed: stay hidden
                }

                this.cfg.strings = this.cfg.strings || {};
                this.cfg.tracks  = this.cfg.tracks  || {};
                this.rate        = this.cfg.rate    || 1;

                this._applyLocale(this.cfg.defaultLocale || 'fil');
                this.available = this._anyPlayable();

                if (!this.available) { return; }

                this._maybeResume();
                whenVoicesReady(this._resolveVoice.bind(this));

                // Never keep talking into a page the resident has left.
                window.addEventListener('pagehide', this.stop.bind(this));
                document.addEventListener('voice-reader:body', this._onBodyReplaced.bind(this));
            },

            /** Is there any language at all this device can actually play? */
            _anyPlayable() {
                var tracks = this.cfg.tracks;
                for (var code in tracks) {
                    if (!Object.prototype.hasOwnProperty.call(tracks, code)) { continue; }
                    if (!tracks[code].available) { continue; }
                    if (tracks[code].audioUrl || tracks[code].altAudioUrl) { return true; }
                    if (SPEECH && tracks[code].chunks && tracks[code].chunks.length) { return true; }
                }
                return false;
            },

            /* ── Language and source ─────────────────────────────────────── */

            get track() {
                return (this.cfg && this.cfg.tracks[this.locale]) || null;
            },

            get localeCode() {
                return this.locale === 'msm' ? 'MN' : this.locale.toUpperCase();
            },

            /** A Manobo post that has both a recording and a generated voice. */
            get hasAlternateSource() {
                var t = this.track;
                return !!(t && t.audioUrl && t.altAudioUrl);
            },

            /** The URL actually in play, honouring the source preference. */
            get activeUrl() {
                var t = this.track;
                if (!t) { return null; }
                if (this.hasAlternateSource) { return this.preferHuman ? t.audioUrl : t.altAudioUrl; }
                return t.audioUrl;
            },

            get canPlay() {
                var t = this.track;
                if (!t || !t.available) { return false; }
                if (this.activeUrl) { return true; }
                if (t.fallback === 'recorded_only') { return this._hasRecordedSegments(); }
                return SPEECH && t.chunks && t.chunks.length > 0;
            },

            /**
             * Whether the "this is an approximation" label is showing.
             *
             * True whenever a Manobo track is about to be spoken by a machine,
             * whichever of the two machine paths it is. False when a community
             * recording is what will play — that is a Manobo speaker, and
             * calling it an approximation would be its own kind of wrong.
             */
            get showApproxLabel() {
                var t = this.track;
                if (!t || !t.approximate || t.fallback === 'recorded_only') { return false; }
                return !(this.activeUrl && this.preferHuman && (t.source === 'human' || t.source === 'dataset'));
            },

            /** One line under the heading saying who, or what, is reading. */
            get sourceLabel() {
                var s = this.cfg ? this.cfg.strings : {};
                var t = this.track;
                if (!t) { return ''; }

                if (this.activeUrl && (!this.hasAlternateSource || this.preferHuman) && t.source === 'dataset') {
                    return t.voiceName ? (t.voiceName + ' (Voice Dataset)') : (s.source_human || '');
                }
                if (this.activeUrl && (!this.hasAlternateSource || this.preferHuman) && t.source === 'human') {
                    return s.source_human || '';
                }
                if (!this.activeUrl && t.fallback === 'recorded_only') {
                    return this._hasRecordedSegments()
                        ? (s.source_recorded_only || '')
                        : (s.no_recordings || '');
                }
                if (!this.activeUrl && this.chunks.some(function (c) { return c.segments && c.segments.length; })) {
                    return s.source_dataset_mix || s.source_device || '';
                }
                if (this.activeUrl) {
                    var voice = (this.hasAlternateSource ? t.altVoiceName : t.voiceName) || '';
                    return t.approximate
                        ? (s.source_approx || '')
                        : (s.source_ai || '').replace(':voice', voice);
                }
                return s.source_device || '';
            },

            /** Switch the player only — no page navigation. Internal use (see _maybeResume()). */
            setLocale(code) {
                var t = this.cfg.tracks[code];
                if (!t || !t.available || code === this.locale) { return; }

                this.stop();
                this._applyLocale(code);
                this._resolveVoice();
            },

            /**
             * What the language buttons actually call.
             *
             * Translates on the spot when this language has no text yet
             * (never disabled, never a dead end), then switches the WHOLE
             * page to it — the mirror of the header switch, so the two can
             * never show different languages at once.
             */
            async chooseLanguage(code) {
                if (this.translating) { return; }

                var t = this.cfg.tracks[code];
                if (!t) { return; }

                if (!t.available) {
                    var ok = await this.requestTranslation(code);
                    if (!ok) { return; }   // stays put; requestTranslation() already left a message
                }

                this._goToLanguage(code);
            },

            /**
             * Ask the server to translate this post into `code` right now.
             * Text only — see VoiceController::translateNow() — so it is fast
             * enough to sit behind one button press, unlike generating audio.
             * Shown as "Isinasalin..." on the button itself, never a permanent
             * grey-out.
             */
            async requestTranslation(code) {
                this.translating = code;
                this.notice      = '';

                try {
                    var base = ((window.BarangGabay && window.BarangGabay.baseUrl) || '').replace(/\/$/, '');
                    var res  = await fetch(base + '/api/voice/translate-now', {
                        method:  'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body:    new URLSearchParams({
                            content_type: this.cfg.type,
                            content_id:   this.cfg.id,
                            locale:       code,
                            csrf_token:   this.cfg.csrfToken || (window.BarangGabay && window.BarangGabay.csrfToken) || '',
                        }),
                    });
                    var data = await res.json();

                    if (!data.success || !data.chunks || !data.chunks.length) {
                        this.notice = data.error || this.cfg.strings.translate_failed || '';
                        return false;
                    }

                    var track = this.cfg.tracks[code];
                    track.chunks     = data.chunks;
                    track.title      = data.title || track.title;
                    track.available  = true;
                    track.speechLang = data.speech_lang || track.speechLang;
                    track.voices     = data.voices || track.voices;

                    this.available = this._anyPlayable();
                    return true;
                } catch (e) {
                    this.notice = this.cfg.strings.translate_failed || '';
                    return false;
                } finally {
                    this.translating = null;
                }
            },

            /**
             * Persist which language and post to resume, then navigate — the
             * exact URL the header language switch itself uses, so there is
             * one true place a page's language is decided, not two.
             */
            _goToLanguage(code) {
                this.stop();

                try {
                    sessionStorage.setItem(RESUME_KEY, JSON.stringify({
                        type: this.cfg.type, id: this.cfg.id, locale: code,
                    }));
                } catch (e) { /* private browsing or storage disabled — the switch still happens */ }

                var url = this.cfg.localeUrls && this.cfg.localeUrls[code];
                if (url) {
                    window.location.href = url;
                } else {
                    this.setLocale(code);   // no URL configured — at least switch the player
                }
            },

            /**
             * Best-effort resume after the reload _goToLanguage() caused.
             *
             * Browsers vary on whether a fresh page load may autoplay audio
             * with no new tap behind it; when one refuses, this simply leaves
             * the player sitting ready on the right language instead of
             * throwing an error the resident would see.
             */
            _maybeResume() {
                var raw;
                try { raw = sessionStorage.getItem(RESUME_KEY); } catch (e) { return; }
                if (!raw) { return; }
                try { sessionStorage.removeItem(RESUME_KEY); } catch (e) {}

                var marker;
                try { marker = JSON.parse(raw); } catch (e) { return; }
                if (!marker || marker.type !== this.cfg.type || marker.id !== this.cfg.id) { return; }

                var t = this.cfg.tracks[marker.locale];
                if (!t || !t.available) { return; }

                if (this.locale !== marker.locale) { this._applyLocale(marker.locale); }
                this.available = this._anyPlayable();

                var self = this;
                whenVoicesReady(function () {
                    self._resolveVoice();
                    setTimeout(function () {
                        try { self.play(); } catch (e) { /* autoplay blocked — button is ready */ }
                    }, 250);
                });
            },

            /** Manobo only: choose between the recording and the generated voice. */
            useSource(human) {
                if (this.preferHuman === !!human) { return; }
                this.stop();
                this.preferHuman = !!human;
            },

            _applyLocale(code) {
                var t = this.cfg.tracks[code];
                if (!t) { return; }

                this.locale      = code;
                this.chunks      = t.chunks || [];
                this.mode        = this.activeUrl ? 'audio' : 'speech';
                this.preferHuman = true;
                if (typeof t.speakingRate === 'number' && t.speakingRate > 0) {
                    this.rate = t.speakingRate;
                }
                this.notice      = t.stale && t.source === 'human'
                    ? (this.cfg.strings.stale_recording || '')
                    : '';
                this.progress    = 0;
                this.current     = -1;
                this._cursor     = 0;
                this._measure();
            },

            /** Cumulative character counts, used for progress and highlighting. */
            _measure() {
                this._total  = 0;
                this._before = [];
                for (var i = 0; i < this.chunks.length; i++) {
                    this._before.push(this._total);
                    this._total += (this.chunks[i].say || '').length;
                }
            },

            /**
             * Choose the device voice for the speech fallback, and say plainly
             * when the device has none for this language. Reading Filipino with
             * an English voice is near-unintelligible, so the resident is told
             * rather than left wondering why it sounds like gibberish.
             */
            _resolveVoice() {
                var t = this.track;
                if (!t) { return; }

                this._voice = pickVoice(t.voices || []);

                if (!this.activeUrl && !this._voice && SPEECH
                    && (window.speechSynthesis.getVoices() || []).length) {
                    var names = (this.cfg.strings.languages || {});
                    this.notice = (this.cfg.strings.no_voice || '')
                        .replace(':language', names[this.locale] || this.locale);
                }
            },

            /* ── Transport ───────────────────────────────────────────────── */

            /**
             * iOS Safari only allows audio that begins inside the user's own
             * tap, so there is deliberately nothing awaited between this click
             * handler and the call that starts playback.
             */
            play() {
                if (!this.canPlay) { return; }
                if (this.status === 'paused') { this.resume(); return; }

                this._stopping = false;
                this._cursor   = 0;
                this._lastMark = -1;
                this.mode      = this.activeUrl ? 'audio' : 'speech';

                if (this.mode === 'audio') {
                    var el = this._audioEl();
                    if (!el) { return; }
                    if (el.getAttribute('src') !== this.activeUrl) { el.src = this.activeUrl; }
                    el.playbackRate = this.rate;
                    el.currentTime  = 0;
                    el.play();
                    this._setStatus('playing');
                    return;
                }

                // Inside the tap: let the dataset clip element play later on iOS.
                if (this.chunks.some(function (c) { return c.segments && c.segments.length; })) {
                    this._segments().unlock();
                }

                this._setStatus('playing');
                this._speakFrom(0);
            },

            pause() {
                if (this.status !== 'playing') { return; }

                if (this.mode === 'audio') {
                    var el = this._audioEl();
                    if (el) { el.pause(); }
                    return;                      // the pause event sets the status
                }

                this._stopTimers();

                // A recorded clip pauses and resumes exactly where it was, on every platform.
                var recOnly = this.track && this.track.fallback === 'recorded_only';
                if (this._seg && this._seg.active && (recOnly || this._seg.clipPlaying())) {
                    this._seg.pause();
                    this._setStatus('paused');
                    return;
                }

                if (ANDROID) {
                    // Android Chrome accepts pause() and then never resumes, so
                    // the sentence is dropped and replayed from its start on
                    // resume. Hearing one sentence twice beats a dead button.
                    this._stopping = true;
                    window.speechSynthesis.cancel();
                } else {
                    window.speechSynthesis.pause();
                }
                this._setStatus('paused');
            },

            resume() {
                if (this.status !== 'paused') { return; }

                if (this.mode === 'audio') {
                    var el = this._audioEl();
                    if (el) { el.play(); }
                    return;
                }

                this._stopping = false;
                this._setStatus('playing');

                if (this._seg && this._seg.active && this._seg.paused
                    && (this._seg._clipPaused || this._seg._pendingRun || (this.track && this.track.fallback === 'recorded_only'))) {
                    this._seg.resume();
                    this._startTimers();
                    return;
                }

                if (ANDROID) {
                    this._speakFrom(Math.max(this.current, 0));
                } else {
                    window.speechSynthesis.resume();
                    this._startTimers();
                }
            },

            toggle() {
                if (this.status === 'playing') { this.pause(); } else { this.play(); }
            },

            stop() {
                this._stopping = true;
                this._stopTimers();

                var el = this._audioEl();
                if (el) { el.pause(); try { el.currentTime = 0; } catch (e) {} }
                if (this._seg) { this._seg.stop(); }
                if (SPEECH) { window.speechSynthesis.cancel(); }

                this.current  = -1;
                this.progress = 0;
                this._lastMark = -1;
                this._clearHighlight();
                this._setStatus('idle');
            },

            /** 0.75 / 1 / 1.25 — older listeners very often want slower. */
            setRate(value) {
                this.rate = parseFloat(value) || 1;

                if (this.mode === 'audio') {
                    var el = this._audioEl();
                    if (el) { el.playbackRate = this.rate; }
                    return;
                }

                // The engine cannot change an utterance already in flight, so a
                // rate change mid-sentence means re-speaking that sentence.
                if (this.status === 'playing') {
                    this._speakFrom(Math.max(this.current, 0));
                }
            },

            /* ── Cached MP3 ──────────────────────────────────────────────── */

            _audioEl() {
                if (!this._audio) { this._audio = this.$el.querySelector('audio[data-voice-audio]'); }
                return this._audio;
            },

            onAudioReady() { /* duration is read lazily in onAudioProgress */ },

            /**
             * Follow the MP3 with the highlight.
             *
             * There are no word-boundary events for recorded audio, so position
             * is mapped onto the sentences by character share. The file was
             * generated from exactly these sentences at one constant rate, so
             * the mapping stays close enough to follow with your eye — and for
             * a human recording it is a genuine approximation, which is why the
             * highlight is a reading aid and never the source of truth.
             */
            onAudioProgress(event) {
                var el = event.target;
                if (!el || !el.duration || !isFinite(el.duration)) { return; }

                this.progress = (el.currentTime / el.duration) * 100;

                if (!this._total || !this.chunks.length) { return; }

                var spoken = (el.currentTime / el.duration) * this._total;
                var index  = 0;
                for (var i = 0; i < this.chunks.length; i++) {
                    if (this._before[i] <= spoken) { index = i; } else { break; }
                }

                if (index !== this._lastMark) {
                    this._lastMark = index;
                    this.current   = index;
                    this._highlight(this.chunks[index].find);
                }
            },

            onAudioPlay()  { this._setStatus('playing'); },

            onAudioPause() {
                var el = this._audioEl();
                if (el && !el.ended) { this._setStatus('paused'); }
            },

            onAudioEnded() {
                this.progress  = 0;
                this.current   = -1;
                this._lastMark = -1;
                this._clearHighlight();
                this._setStatus('idle');
            },

            /**
             * The cached file is gone or unplayable — a cleared uploads folder,
             * a half-written file. Fall through to the device voice rather than
             * leaving a button that does nothing.
             */
            onAudioError() {
                if (this.status === 'idle') { return; }

                this.notice = this.cfg.strings.audio_failed || '';
                this.mode   = 'speech';

                if (SPEECH && this.chunks.length) {
                    this._setStatus('playing');
                    this._speakFrom(0);
                } else {
                    this.stop();
                }
            },

            /* ── Device speech ───────────────────────────────────────────── */

            _speakFrom(index) {
                var recordedOnly = this.track && this.track.fallback === 'recorded_only';
                if (!SPEECH && !recordedOnly) { return; }

                if (this._seg) { this._seg.stop(); }
                if (SPEECH) { window.speechSynthesis.cancel(); }
                this._stopping = false;
                if (recordedOnly && this.chunks.some(function (c) {
                    return c.segments && c.segments.some(function (sg) { return sg.type === 'missing'; });
                })) {
                    this.notice = (this.cfg.strings && this.cfg.strings.some_missing) || '';
                }
                this._startTimers();
                this._speak(index);
            },

            _speak(index) {
                if (this._stopping) { return; }
                if (index >= this.chunks.length) { this._finish(); return; }

                var chunk = this.chunks[index];
                var track = this.track;
                var self  = this;

                // A sentence that contains approved native recordings plays
                // through the segment player: recorded clips (longest phrase
                // first) with the device voice reading only the unrecorded
                // words. Its own <audio> element, so the cached-MP3 handlers
                // bound to [data-voice-audio] never see these clips.
                if (chunk && chunk.segments && chunk.segments.length) {
                    this.current   = index;
                    this._spokenAt = Date.now();
                    this._highlight(chunk.find);
                    this._progressAt(index, 0);

                    this._segments().play(chunk.segments, {
                        fallback: track && track.fallback,
                        lang:  (track && track.speechLang) || 'fil-PH',
                        voice: this._voice,
                        rate:  this.rate,
                        onSegment: function () { self._spokenAt = Date.now(); },
                        onDone: function () {
                            if (self._stopping) { return; }
                            self._progressAt(index, (chunk.say || '').length);
                            self._speak(index + 1);
                        },
                        onSpeechError: function () {
                            self.notice = self.cfg.strings.speech_failed || '';
                            self.stop();
                        },
                    });
                    return;
                }

                // Recorded-only: a sentence with no plan has nothing to play.
                if (track && track.fallback === 'recorded_only') {
                    var self2 = this;
                    setTimeout(function () { if (!self2._stopping) { self2._speak(index + 1); } }, 0);
                    return;
                }

                this._speakUtterance(index, chunk, track);
            },

            /** Whether any sentence has at least one approved recording to play. */
            _hasRecordedSegments() {
                return this.chunks.some(function (c) {
                    return c.segments && c.segments.some(function (sg) { return sg.type === 'recorded'; });
                });
            },

            /** The dataset segment player for this reader (created on first use). */
            _segments() {
                if (!this._seg) { this._seg = new VoiceSegmentPlayer(); }
                return this._seg;
            },

            _speakUtterance(index, chunk, track) {
                var self = this;
                var u    = new SpeechSynthesisUtterance(chunk.say);

                u.lang   = (track && track.speechLang) || 'fil-PH';
                u.rate   = this.rate;
                u.pitch  = 1;
                u.volume = 1;
                if (this._voice) { u.voice = this._voice; }

                u.onstart = function () {
                    self.current   = index;
                    self._spokenAt = Date.now();
                    self._highlight(chunk.find);
                    self._progressAt(index, 0);
                };

                u.onboundary = function (event) {
                    self._spokenAt = Date.now();
                    self._progressAt(index, event.charIndex || 0);
                };

                u.onend = function () {
                    if (self._stopping) { return; }
                    self._speak(index + 1);
                };

                u.onerror = function (event) {
                    // cancel() raises these on every queued utterance; they are
                    // this player's own doing, not a failure.
                    if (self._stopping || event.error === 'interrupted' || event.error === 'canceled') { return; }
                    self.notice = self.cfg.strings.speech_failed || '';
                    self.stop();
                };

                this.current   = index;
                this._spokenAt = Date.now();
                window.speechSynthesis.speak(u);
            },

            _finish() {
                this._stopTimers();
                this.current  = -1;
                this.progress = 0;
                this._clearHighlight();
                this._setStatus('idle');
            },

            /**
             * Two timers guard the same Chrome bug from different sides: the
             * keep-alive nudges an engine that stops speaking mid-queue, and
             * the watchdog restarts the queue if it went silent anyway.
             */
            _startTimers() {
                var self = this;
                this._stopTimers();

                this._keepAlive = setInterval(function () {
                    if (self.status === 'playing' && self.mode === 'speech' && SPEECH) {
                        window.speechSynthesis.resume();
                    }
                }, 9000);

                this._watchdog = setInterval(function () {
                    if (self.status !== 'playing' || self.mode !== 'speech' || !SPEECH) { return; }
                    if (self.track && self.track.fallback === 'recorded_only') { return; }   // clips only; no engine to restart
                    if (window.speechSynthesis.speaking || window.speechSynthesis.pending) { return; }
                    // A recorded dataset clip is sounding: silence from the speech engine is expected.
                    // (Includes the moment a clip is still loading over a slow connection.)
                    if (self._seg && self._seg.active && !self._seg.paused) { self._spokenAt = Date.now(); return; }
                    if (Date.now() - self._spokenAt < 2000) { return; }

                    self._speak(self.current + 1);   // went quiet without firing onend
                }, 1000);
            },

            _stopTimers() {
                if (this._keepAlive) { clearInterval(this._keepAlive); this._keepAlive = null; }
                if (this._watchdog) { clearInterval(this._watchdog); this._watchdog = null; }
            },

            /* ── Highlighting ────────────────────────────────────────────── */

            _bodyEl() {
                return this.cfg && this.cfg.bodySelector
                    ? document.querySelector(this.cfg.bodySelector)
                    : null;
            },

            /**
             * Mark the sentence being read.
             *
             * A chunk whose text is not on the page is simply not found and
             * nothing is highlighted. That is the expected case rather than an
             * error — it covers the spoken date line, an ordinance summary
             * shown elsewhere, and a resident listening in a language other
             * than the one the page is currently showing.
             */
            _highlight(find) {
                var el = this._bodyEl();
                if (!el) { return; }
                if (this._bodyHTML === null) { this._bodyHTML = el.innerHTML; }

                el.innerHTML = this._bodyHTML;              // drop the previous mark
                if (!find) { return; }

                var needle = String(find).replace(/\s+/g, ' ').trim();
                if (!needle) { return; }

                var index = this._index(el);
                var start = index.text.indexOf(needle, this._cursor);
                if (start === -1) { start = index.text.indexOf(needle); }   // wrap once
                if (start === -1) { return; }

                this._cursor = start + needle.length;

                var first = index.map[start];
                var last  = index.map[start + needle.length - 1];
                if (!first || !last) { return; }

                var range = document.createRange();
                range.setStart(first.node, first.offset);
                range.setEnd(last.node, last.offset + 1);
                this._wrap(range, el);
                this._reveal(el);
            },

            /**
             * Map every character of the element's whitespace-collapsed text
             * back to the text node and offset it came from. The collapsing
             * mirrors SpokenText::normalise() on the server, which is what lets
             * a sentence built there be found here.
             */
            _index(el) {
                var walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, null, false);
                var text   = '';
                var map    = [];
                var node;

                while ((node = walker.nextNode())) {
                    var value = node.nodeValue || '';
                    for (var i = 0; i < value.length; i++) {
                        if (/\s/.test(value[i])) {
                            if (!text.length || text[text.length - 1] === ' ') { continue; }
                            text += ' ';
                        } else {
                            text += value[i];
                        }
                        map.push({ node: node, offset: i });
                    }
                }
                return { text: text, map: map };
            },

            /** Wrap a range in <mark>, splitting text nodes where it crosses tags. */
            _wrap(range, root) {
                var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
                var nodes  = [];
                var node;

                while ((node = walker.nextNode())) {
                    if (range.intersectsNode(node)) { nodes.push(node); }
                }

                for (var i = 0; i < nodes.length; i++) {
                    var n    = nodes[i];
                    var from = n === range.startContainer ? range.startOffset : 0;
                    var to   = n === range.endContainer   ? range.endOffset   : (n.nodeValue || '').length;
                    if (to <= from) { continue; }

                    var target = n;
                    if (from > 0) { target = target.splitText(from); }
                    if ((to - from) < (target.nodeValue || '').length) { target.splitText(to - from); }

                    var mark = document.createElement('mark');
                    mark.className = 'voice-mark';
                    target.parentNode.insertBefore(mark, target);
                    mark.appendChild(target);
                }
            },

            /** Scroll the mark into view only when it has actually gone off it. */
            _reveal(el) {
                var mark = el.querySelector('.voice-mark');
                if (!mark) { return; }

                var box = mark.getBoundingClientRect();
                if (box.top > 90 && box.bottom < window.innerHeight - 140) { return; }

                mark.scrollIntoView({ block: 'center', behavior: REDUCED ? 'auto' : 'smooth' });
            },

            _clearHighlight() {
                var el = this._bodyEl();
                if (el && this._bodyHTML !== null) { el.innerHTML = this._bodyHTML; }
                this._cursor = 0;
            },

            /* ── Late-arriving text (the AI ordinance summary) ────────────── */

            /**
             * The resident pressed "Summarize with AI" after this page loaded,
             * so there is now something worth reading that did not exist at
             * render time. Only the device-speech script is replaced: no MP3
             * exists for text that was generated seconds ago, and synthesising
             * one on a resident's page view is exactly what this design avoids.
             */
            async _onBodyReplaced(event) {
                var text = event && event.detail ? event.detail.text : '';
                if (!text || !this.cfg) { return; }

                var target = event.detail.locale || 'fil';
                var track  = this.cfg.tracks[target];
                if (!track) { return; }

                try {
                    var base = ((window.BarangGabay && window.BarangGabay.baseUrl) || '').replace(/\/$/, '');
                    var res  = await fetch(base + '/api/voice/script', {
                        method:  'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body:    new URLSearchParams({
                            body:         text,
                            body_is_html: '0',
                            title:        track.title || '',
                            locale:       target,
                            csrf_token:   (window.BarangGabay && window.BarangGabay.csrfToken) || '',
                        }),
                    });
                    var data = await res.json();
                    if (!data.success || !data.chunks.length) { return; }

                    // Pick up native dataset recordings for the new wording too.
                    try {
                        var form = new URLSearchParams({
                            language:   target,
                            csrf_token: (window.BarangGabay && window.BarangGabay.csrfToken) || '',
                        });
                        data.chunks.forEach(function (c) { form.append('texts[]', c.say || ''); });
                        var planRes = await fetch(base + '/api/voice/resolve', {
                            method:  'POST',
                            headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'X-Requested-With': 'XMLHttpRequest' },
                            body:    form,
                        });
                        var plans = await planRes.json();
                        if (plans.success && plans.plans) {
                            data.chunks.forEach(function (c, i) { if (plans.plans[i]) { c.segments = plans.plans[i]; } });
                            if (plans.fallback) { track.fallback = plans.fallback; }
                        }
                    } catch (e) { /* no recordings — the device voice reads it all */ }

                    track.chunks    = data.chunks;
                    track.available = true;
                    if (this.locale === target && !this.activeUrl) {
                        this.stop();
                        this.chunks = data.chunks;
                        this._measure();
                    }
                    this.available = this._anyPlayable();
                } catch (e) {
                    /* Keep whatever script we already had — it still reads. */
                }
            },

            /* ── Small helpers ───────────────────────────────────────────── */

            _progressAt(index, charIndex) {
                if (!this._total) { return; }
                var length = (this.chunks[index].say || '').length || 1;
                var spoken = this._before[index] + Math.min(charIndex, length);
                this.progress = Math.min((spoken / this._total) * 100, 100);
            },

            _setStatus(status) {
                this.status = status;

                // The mini player takes the bottom of the screen while it is
                // visible; this moves the chat launcher and the back-to-top
                // button up so nothing is stacked on top of the stop button.
                document.body.classList.toggle('voice-playing', status !== 'idle');

                var strings = (this.cfg && this.cfg.strings) || {};
                this.statusText = status === 'playing' ? (strings.status_playing || '')
                    : status === 'paused'              ? (strings.status_paused  || '')
                    :                                    (strings.status_idle    || '');
            },
        };
    };

    /**
     * Staff preview — "how will this sound before I publish it?"
     *
     * Reads whatever is currently typed in the form, asks the server to prepare
     * it exactly as a resident's page would, and speaks it with the device
     * voice. Deliberately the device voice and not the provider: this runs on
     * every keystroke-and-listen cycle while an editor works, and spending the
     * barangay's free tier on drafts nobody will ever hear is how the budget
     * for the published version disappears. What it catches — "Brgy." read
     * literally, a missing full stop running two sentences together — is
     * identical either way.
     */
    window.voicePreview = function () {
        return {
            supported: SPEECH,
            locale:   'fil',
            speaking: false,
            busy:     false,
            message:  '',
            rate:     1,
            _chunks:  [],
            _lang:    null,
            _voice:   null,
            _cfg:     { strings: {} },
            _stopping: false,

            init() {
                var raw = this.$el.querySelector('script[data-voice-preview-config]');
                if (raw) {
                    try { this._cfg = JSON.parse(raw.textContent || '{}'); } catch (e) {}
                }
                this._cfg.strings = this._cfg.strings || {};
                this.locale       = this._cfg.locale  || 'fil';
            },

            /** Pull text out of the form the same way the Manobo drafter does. */
            _field(names) {
                var form = this.$el.closest('form');
                if (!form) { return ''; }

                for (var i = 0; i < names.length; i++) {
                    var field = form.querySelector('[name="' + names[i] + '"]');
                    if (field && (field.value || '').trim()) { return field.value.trim(); }
                }
                return '';
            },

            /**
             * Which fields each preview language reads.
             *
             * Manobo previews the Manobo fields — and is spoken by the Filipino
             * voice, because no Manobo voice exists. That is the same
             * approximation residents get, so staff hear exactly what will be
             * published rather than a better version of it.
             */
            _source() {
                if (this.locale === 'en') {
                    return {
                        title: this._field(['title_en', 'title']),
                        body:  this._field(['body_en', 'description_en', 'body', 'description']),
                    };
                }
                if (this.locale === 'msm') {
                    return {
                        title: this._field(['title_manobo']),
                        body:  this._field(['body_manobo', 'description_manobo']),
                    };
                }
                return {
                    title: this._field(['title']),
                    body:  this._field(['body', 'description']),
                };
            },

            async toggle() {
                if (this.speaking) { this.stop(); return; }
                if (this.busy) { return; }

                var src = this._source();
                if (!src.title && !src.body) { this.message = this._cfg.strings.empty; return; }

                // Date and venue are what a listener needs first on an event,
                // so preview them where a resident would hear them.
                var lead  = [];
                var venue = this._field(['venue']);
                var when  = this._field(['event_date']);
                if (when)  { lead.push(this._cfg.strings.date_label  + ' ' + when.replace('T', ' ')); }
                if (venue) { lead.push(this._cfg.strings.venue_label + ' ' + venue); }

                this.busy    = true;
                this.message = '';

                try {
                    var base = ((window.BarangGabay && window.BarangGabay.baseUrl) || '').replace(/\/$/, '');
                    var res  = await fetch(base + '/api/voice/script', {
                        method:  'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body:    new URLSearchParams({
                            title:      src.title,
                            body:       src.body,
                            lead:       lead.join('\n'),
                            locale:     this.locale,
                            csrf_token: (window.BarangGabay && window.BarangGabay.csrfToken) || '',
                        }),
                    });
                    var data = await res.json();

                    if (!data.success || !data.chunks.length) {
                        this.message = data.error || this._cfg.strings.empty;
                        return;
                    }

                    this._chunks = data.chunks;
                    this._lang   = data.speech_lang;
                    this._voice  = pickVoice(data.voices || []);
                    if (!this._voice) { this.message = this._cfg.strings.no_voice; }

                    this.speaking  = true;
                    this._stopping = false;
                    this._speak(0);
                } catch (e) {
                    this.message = this._cfg.strings.failed;
                } finally {
                    this.busy = false;
                }
            },

            _speak(index) {
                if (this._stopping) { return; }
                if (index >= this._chunks.length) { this.speaking = false; return; }

                var self = this;
                var u    = new SpeechSynthesisUtterance(this._chunks[index].say);
                u.lang   = this._lang || 'fil-PH';
                u.rate   = this.rate;
                if (this._voice) { u.voice = this._voice; }

                u.onend   = function () { if (!self._stopping) { self._speak(index + 1); } };
                u.onerror = function () { self.speaking = false; };

                window.speechSynthesis.speak(u);
            },

            stop() {
                this._stopping = true;
                this.speaking  = false;
                if (SPEECH) { window.speechSynthesis.cancel(); }
            },
        };
    };

    /**
     * Admin generation panel — per-language status and a button to build the
     * cached narration. Publishing already does this automatically; this is
     * for regenerating after an edit and for retrying a provider hiccup.
     */
    window.voiceGenerator = function () {
        return {
            busy:     '',
            error:    '',
            statuses: {},
            cfg:      { strings: {}, locales: [] },

            init() {
                var raw = this.$el.querySelector('script[data-voice-generator-config]');
                if (raw) {
                    try { this.cfg = JSON.parse(raw.textContent || '{}'); } catch (e) {}
                }
                this.cfg.strings = this.cfg.strings || {};
                this.statuses    = this.cfg.statuses || {};
            },

            stateOf(locale) {
                return (this.statuses[locale] || {}).state || 'none';
            },

            label(locale) {
                var state = this.stateOf(locale);
                return (this.cfg.strings.states || {})[state] || state;
            },

            stateClass(locale) {
                var state = this.stateOf(locale);
                if (state === 'ready' || state === 'human') { return 'voice-state-ok'; }
                if (state === 'stale' || state === 'human_stale') { return 'voice-state-stale'; }
                if (state === 'unavailable') { return 'voice-state-off'; }
                return 'voice-state-none';
            },

            voiceOf(locale)  { return (this.statuses[locale] || {}).voiceName || ''; },
            charsOf(locale)  { return (this.statuses[locale] || {}).chars || 0; },

            async generate(locale) {
                if (this.busy) { return; }
                this.busy  = locale || 'all';
                this.error = '';

                try {
                    var base = ((window.BarangGabay && window.BarangGabay.baseUrl) || '').replace(/\/$/, '');
                    var res  = await fetch(base + '/api/admin/voice/generate', {
                        method:  'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body:    new URLSearchParams({
                            type:       this.cfg.type || '',
                            id:         this.cfg.id   || 0,
                            locale:     locale || '',
                            csrf_token: (window.BarangGabay && window.BarangGabay.csrfToken) || '',
                        }),
                    });
                    var data = await res.json();

                    if (!data.success) { this.error = data.error || this.cfg.strings.failed; return; }
                    this.statuses = data.statuses || this.statuses;
                } catch (e) {
                    this.error = this.cfg.strings.failed;
                } finally {
                    this.busy = '';
                }
            },
        };
    };
}());
